mapper.select:
select proj.*
from proj_establish_base_info proj left join proj_review_base_info pr on proj.id = pr.proj_establish_id and pr.proj_review_status !='CLOSED' and pr.proj_review_status != 'EXPIRE'

    and proj.client_id=#{dto.clientId}
    and proj.proj_name like CONCAT('%',#{dto.projName},'%')
    and proj.proj_code like CONCAT('%',#{dto.projCode}, '%')
    
    and proj.biz_type = #{dto.bizType}
    and proj.biz_dept_id=#{dto.bizDeptId}
    and proj.proj_sponsor_user_id=#{dto.projSponsorUserId}
    
        and json_contains(proj.proj_cosponsor_user_ids, CONVERT(#{dto.projCosponsorUserId},CHAR))
    
    and proj.proj_establish_status=#{dto.projEstablishStatus}
    and
        proj.proj_establish_process_status=#{dto.projEstablishProcessStatus}
    
    and proj.create_time >= #{dto.createFrom}
    and proj.create_time <= #{dto.createTo}
    and proj.update_time >= #{dto.updateFrom}
    and proj.update_time <= #{dto.updateTo}
    

order by update_time desc

select proj.*, GROUP_CONCAT(distinct c.contract_status) as contractStatuses, IF(proj.projReviewId IS NULL, 'PROJESTABLISH_STAGE', IF(c.id IS NULL, 'PROJREVIEW_STAGE', IF(GROUP_CONCAT(distinct c.contract_status) != 'SETTLE', 'CONTRACT_STAGE', 'CONTRACTSETTLE_STAGE'))) AS projStage from ( select e.id, CONCAT(e.id, 'ESTABLISH') as `key`, proj_name projName, client_id clientId, IF(pr.id IS NOT NULL, pr.proj_sponsor_user_id, e.proj_sponsor_user_id) projSponsorUserId, IF(pr.id IS NOT NULL, pr.proj_cosponsor_user_ids, e.proj_cosponsor_user_ids) projCosponsorUserIds, biz_dept_id bizDeptId, biz_type bizType, lease_types leaseTypes, create_time createTime, 'PROJ_ESTABLISH' as dataType, proj_establish_status as projStatus, pr.id AS projReviewId, pr.proj_review_status AS projReviewStatus from proj_establish_base_info e LEFT JOIN (select id,proj_review_status,proj_establish_id,proj_sponsor_user_id,proj_cosponsor_user_ids from proj_review_base_info pt1) pr ON e.id = pr.proj_establish_id AND pr.proj_review_status != 'CLOSED' where proj_establish_status != 'CLOSED' and proj_establish_status != 'EXPIRE' union all select * from ( select id, CONCAT(id, 'REVIWE') as `key`, proj_name projName, client_id clientId, proj_sponsor_user_id projSponsorUserId, proj_cosponsor_user_ids projCosponsorUserIds, biz_dept_id bizDeptId, biz_type bizType, lease_types leaseTypes, create_time createTime, 'GROUP_CREDIT_REVIEW' as dataType, proj_review_status as projStatus, id AS projReviewId, proj_review_status AS projReviewStatus from proj_review_base_info t1 where t1.relation_data_type = 'GROUP_CREDIT_REVIEW' and t1.proj_review_status != 'CLOSED' and t1.proj_review_status != 'EXPIRE') r ) proj left join contract_base_info c on c.proj_review_id = proj.projReviewId where proj.projStatus != 'PEND_TAKE_EFFECT' and proj.projStatus != 'CLOSED' and (proj.projReviewId is null or proj.projReviewStatus != 'PEND_TAKE_EFFECT') and proj.clientId IN
#{item}
group by proj.`key` order by proj.clientId desc
